macro_rules! messages {
    () => {
        mod messages { use crate :: backend :: c ; use crate :: backend :: net :: msghdr ; use core :: iter :: FusedIterator ; use core :: marker :: PhantomData ; use core :: mem :: MaybeUninit ; use core :: ptr :: NonNull ; # [doc = " An iterator over the messages in an ancillary buffer."] pub (super) struct Messages < 'buf > { # [doc = " The message header we're using to iterate over the messages."] msghdr : c :: msghdr , # [doc = " The current pointer to the next message header to return."] # [doc = ""] # [doc = " This has a lifetime of `'buf`."] header : Option < NonNull < c :: cmsghdr > > , # [doc = " Capture the original lifetime of the buffer."] _buffer : PhantomData < & 'buf mut [MaybeUninit < u8 >] > , } pub (super) trait AllowedMsgBufType { } impl AllowedMsgBufType for u8 { } impl AllowedMsgBufType for MaybeUninit < u8 > { } impl < 'buf > Messages < 'buf > { # [doc = " Create a new iterator over messages from a byte buffer."] pub (super) fn new (buf : & 'buf mut [impl AllowedMsgBufType]) -> Self { let mut msghdr = msghdr :: zero_msghdr () ; msghdr . msg_control = buf . as_mut_ptr () . cast () ; msghdr . msg_controllen = buf . len () . try_into () . expect ("buffer too large for msghdr") ; let header = NonNull :: new (unsafe { c :: CMSG_FIRSTHDR (& msghdr) }) ; Self { msghdr , header , _buffer : PhantomData , } } } impl < 'a > Iterator for Messages < 'a > { type Item = & 'a mut c :: cmsghdr ; # [inline] fn next (& mut self) -> Option < Self :: Item > { let header = self . header ? ; self . header = NonNull :: new (unsafe { c :: CMSG_NXTHDR (& self . msghdr , header . as_ptr ()) }) ; if Some (header) == self . header { self . header = None ; } Some (unsafe { & mut * header . as_ptr () }) } fn size_hint (& self) -> (usize , Option < usize >) { if self . header . is_some () { let max_size = unsafe { c :: CMSG_LEN (0) } as usize ; let remaining_count = self . msghdr . msg_controllen as usize / max_size ; (1 , Some (remaining_count)) } else { (0 , Some (0)) } } } impl FusedIterator for Messages < '_ > { } }
    };
}

messages!();